-- GenDB engine variant Q22-always_true_conjunct: template q22.sql, kind always_true_conjunct (generated by generate.py; frozen)
SELECT
  cntrycode,
  COUNT(*) AS numcust,
  SUM(c_acctbal) AS totacctbal
FROM (
  SELECT
    SUBSTRING(c_phone FROM 1 FOR 2) AS cntrycode,
    c_acctbal
  FROM customer
  WHERE
    SUBSTRING(c_phone FROM 1 FOR 2) IN ($1, $2, $3, $4, $5, $6, $7)
    AND c_acctbal > (
      SELECT
        AVG(c_acctbal)
      FROM customer
      WHERE
        c_acctbal > 0.00
        AND SUBSTRING(c_phone FROM 1 FOR 2) IN ($1, $2, $3, $4, $5, $6, $7)
    )
    AND NOT EXISTS(
      SELECT
        *
      FROM orders
      WHERE
        o_custkey = c_custkey
    )
    AND c_custkey = c_custkey
) AS custsale
GROUP BY
  cntrycode
ORDER BY
  cntrycode
